import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    a = int(input[0])
    b = int(input[1])
    m = int(input[2])
    edges = [(int(input[2 + 2 * i]) - 1, int(input[3 + 2 * i]) - 1) for i in range(m)]

    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    edge_colors = [0] * m
    color_count = 0

    for i in range(m):
        if edge_colors[i] == 0:
            u, v = edges[i]
            used_colors = set()
            for neighbor in adj_list[u]:
                if (u, neighbor) in edges:
                    used_colors.add(edge_colors[edges.index((u, neighbor))])
                if (neighbor, u) in edges:
                    used_colors.add(edge_colors[edges.index((neighbor, u))])
            for neighbor in adj_list[v]:
                if (v, neighbor) in edges:
                    used_colors.add(edge_colors[edges.index(((v, neighbor))])
                if (neighbor, v) in edges:
                    used_colors.add(edge_colors[edges.index((neighbor,v))])
            for color in range(1, m + 1):
                if color not in used_colors:
                    edge_colors[i] = color
                    color_count = max(color_count, color)
                    break

    print(color_count)
    print(" ".join(map(str, edge_colors)))

main()
